using System;using System.Collections;using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEngine.InputSystem;
namespace DeadQuarantine.Development {public sealed partial class Phase6WeaponsSmokeDriver {
 Transform BonePose(Animator a,string generic,HumanBodyBones human)=>a.isHuman?a.GetBoneTransform(human):WeaponAttachments.Find(a.transform,generic);
 Transform[] RightArmPose(Animator a)=>new[]{BonePose(a,"upperarm_r",HumanBodyBones.RightUpperArm),BonePose(a,"lowerarm_r",HumanBodyBones.RightLowerArm),BonePose(a,"hand_r",HumanBodyBones.RightHand)};
 void CheckColdPose(Animator animator,string id,string view){var b=RightArmPose(animator);Check(b.All(t=>t),id+" "+view+" right arm has all bones");float angle=Vector3.Angle(b[0].position-b[1].position,b[2].position-b[1].position);Note7(angle<178,id+" "+view+" cold equipped arm is not bind/T pose ("+angle+")");}
 void CheckSupportPose(Animator a,PackWeaponPresentation profile,GameObject model,string label,bool third){var selected=model.GetComponent<WeaponAttachments>();var pose=profile.SupportPose(selected,third);if(pose==null)return;var socket=profile.SupportFrame(selected,WeaponAttachments.Find(model.transform,"SOCKET_Grip"));var hand=BonePose(a,"hand_l",HumanBodyBones.LeftHand);float distance=Vector3.Distance(hand.position,socket.TransformPoint(pose.position));Note7(distance<.025f,label+" support hand reaches actual selected hold target ("+distance+")");if(selected&&selected.ApprovedChoice.support=="Grip_01"){var grip=WeaponAttachments.Find(model.transform,"DQ_ATT_Grip_01");var bounds=WeaponAttachments.BoundsIn(grip.gameObject,socket);float clearance=Mathf.Sqrt(bounds.SqrDistance(socket.InverseTransformPoint(hand.position)));Note7(clearance<.12f,label+" wrist is next to the mounted grip mesh ("+clearance+")");}}
 IEnumerator VerifyWeaponPoses(){
  Local.ShowLocalBodyForTesting=false;var nwa=Local.GetComponent<NetworkWeaponAttachments>();var ids=Local.Weapons.Select(w=>w.Id).Where(id=>string.IsNullOrEmpty(Arg("-dq-pose-ids"))||Arg("-dq-pose-ids").Split(',').Contains(id)).ToArray();
  foreach(var id in ids){int index=Array.FindIndex(Local.Weapons,d=>d.Id==id);Local.Switcher.UnlockWeapon(id);yield return Until(()=>Local.Switcher.CurrentWeaponIndex==index&&!Local.Switcher.IsSwitching,id+" equip");var weapon=Local.Switcher.CurrentWeapon;weapon.InputLocked=false;var rig=Local.Switcher.GetComponent<Animator>();var profile=weapon.GetComponent<PackWeaponPresentation>();
   yield return Select8(nwa,index,id,default);yield return new WaitForEndOfFrame();CheckColdPose(rig,id,"FP before any reload");if(!profile.preserveLegacyAnimation)for(int l=1;l<rig.layerCount;l++)if(rig.GetCurrentAnimatorClipInfo(l).Length==0)Note7(rig.GetLayerWeight(l)<.001f,id+" empty FP layer releases bind pose: "+rig.GetLayerName(l));CheckSupportPose(rig,profile,weapon.gameObject,id+" bare FP",false);Capture(role+"-"+id+"-cold-FP.png");var before=RightArmPose(rig).Select(b=>b.localRotation).ToArray();
   yield return Until(()=>Remote.EquippedIndex==index&&Remote.VisibleWeapon&&!Remote.BodyAnimator.GetBool("TP_Holstering")&&!Remote.BodyAnimator.GetBool("TP_Unholstering"),id+" remote first equipped frame");yield return new WaitForEndOfFrame();CheckColdPose(Remote.BodyAnimator,id,"TP before reload");CheckSupportPose(Remote.BodyAnimator,profile,Remote.VisibleWeapon,id+" bare TP",true);CaptureRemote("pose-"+id+"-cold");
   if(profile.supportPoseEnabled){yield return Select8(nwa,index,id,new WeaponAttachmentChoice{support="Grip_01"});yield return new WaitForEndOfFrame();CheckSupportPose(rig,profile,weapon.gameObject,id+" grip FP",false);CheckSupportPose(Remote.BodyAnimator,profile,Remote.VisibleWeapon,id+" grip TP",true);Capture(role+"-"+id+"-grip-FP.png");CaptureRemote("pose-"+id+"-grip");yield return Select8(nwa,index,id,default);yield return new WaitForEndOfFrame();CheckSupportPose(rig,profile,weapon.gameObject,id+" remove grip FP",false);CheckSupportPose(Remote.BodyAnimator,profile,Remote.VisibleWeapon,id+" remove grip TP",true);}
   weapon.SendMessage("OnAimStarted",default(InputAction.CallbackContext));yield return new WaitForSeconds(.7f);yield return new WaitForEndOfFrame();Check(weapon.IsAiming,id+" aims");if(profile.alignIronSightLine){var physical=WeaponAttachments.Find(weapon.transform,"root");var camera=(Camera)Field7(weapon,"weaponCamera");var rear=camera.WorldToViewportPoint(physical.TransformPoint(profile.ironRear));var front=camera.WorldToViewportPoint(physical.TransformPoint(profile.ironFront));Note7(Vector2.Distance(new Vector2(rear.x,rear.y),Vector2.one*.5f)<.015f&&Vector2.Distance(new Vector2(front.x,front.y),Vector2.one*.5f)<.015f,id+" actual rear aperture and front post both align ("+rear+" / "+front+")");Capture(role+"-Burst-iron-line.png");}weapon.SendMessage("TryFire");yield return new WaitForSeconds(.6f);if(profile.alignIronSightLine){var points=(List<Vector3>)Field7(weapon,"presentationTargets");Check(points.Count>0,id+" actual shot produces a trail endpoint");var camera=(Camera)Field7(weapon,"playerCamera");var vp=camera.WorldToViewportPoint(points.Last());Note7(vp.z>0&&Vector2.Distance(new Vector2(vp.x,vp.y),Vector2.one*.5f)<.04f,id+" real burst ray/trail follows the sight ("+vp+")");}weapon.SendMessage("OnAimCanceled",default(InputAction.CallbackContext));yield return Until(()=>!weapon.IsChambering,id+" chamber",8);yield return new WaitForSeconds(.7f);
   weapon.RestaurarMunicion(weapon.CapacidadCargador-1,100);weapon.SendMessage("OnReload",default(InputAction.CallbackContext));yield return Until(()=>!weapon.IsReloading,id+" reload",25);yield return new WaitForSeconds(.4f);yield return new WaitForEndOfFrame();CheckColdPose(rig,id,"FP after reload");float difference=RightArmPose(rig).Select((b,i)=>Quaternion.Angle(before[i],b.localRotation)).Max();Note7(profile.preserveLegacyAnimation||difference<20,id+" reload is not required to initialize idle (right arm delta="+difference+")");CheckSupportPose(rig,profile,weapon.gameObject,id+" FP after reload",false);Capture(role+"-"+id+"-after-reload.png");
   yield return Barrier("poses-"+id+"-done");
  }
  Complete(phase7Issues.Count==0,string.Join("\n",phase7Issues));
 }
}}
